INSERT INTO `info_parc` (`Id_parc`, `Taille_parc`, `Nom_parc`, `Prix_parc`, `Status_parc`, `Exposition`, `Equipements`, `Preferences`, `Description`, `Chemin_image`, `Id_res`) VALUES
('OP_001', 300, 'Jardin Soleil', 4500.00, 'occupe', 'Une parcelle lumineuse et bien protégée, parfaite pour les cultures nécéssitant beaucoup de soleil. Situé en zone urbaine, elle offre un accès facile et une atmosphère conviviale.', 'Point d\'eau, clôture sécurisée, petit abri de stockage', 'Une parcelle lumineuse et bien protégée, parfaite pour les cultures nécéssitant beaucoup de soleil. Situé en zone urbaine, elle offre un accès facile et une atmosphère conviviale.', '                Une parcelle lumineuse et bien protégée, parfaite pour les cultures nécéssitant beaucoup de soleil. Situé en zone urbaine, elle offre un accès facile et une atmosphère conviviale.            ', '../../../public/uploads/carre-potager-bois-exotique.jpg', 62),
('OP_002', 350, 'Terre Verte', 3200.00, 'occupe', 'Une parcelle pratique et fonctionnelle, idéale pour débuter un projet agricole urbain. La proximité des équipements partagés en fait un choix économique et efficace.', 'Réservoir d\'eau, outils partagés, accès électrique', 'Une parcelle pratique et fonctionnelle, idéale pour débuter un projet agricole urbain. La proximité des équipements partagés en fait un choix économique et efficace.', '                Une parcelle pratique et fonctionnelle, idéale pour débuter un projet agricole urbain. La proximité des équipements partagés en fait un choix économique et efficace.            ', '../../../public/uploads/carre-potager-3etages-bois-nourricier.webp', 63),
('OP_003', 400, 'Verger Urbain', 6800.00, 'occupe', 'Un espace généreux avec système d\'irrigation intégré, pensé pour les passionnés de vergers urbains. La lumière douce du matin favorise une croissance équilibrée.', 'Irrigation goutte-à-goutte, composteur, espace de repos', 'Un espace généreux avec système d\'irrigation intégré, pensé pour les passionnés de vergers urbains. La lumière douce du matin favorise une croissance équilibrée.', '                Un espace généreux avec système d\'irrigation intégré, pensé pour les passionnés de vergers urbains. La lumière douce du matin favorise une croissance équilibrée.            ', '../../../public/uploads/cpe-120x120-t.jpg', 64),
('OP_004', 350, 'Oasis Citadine', 5500.00, 'occupe', 'Une parcelle moderne et polyvalente, équipée pour accueillir des projets innovants. L\'association d\'une serre et d\'un système écologique en fait un espace durable et inspirant.', 'Serre tunnel, système de récupération d\'eau de pluie, éclairage solaire', 'Une parcelle moderne et polyvalente, équipée pour accueillir des projets innovants. L\'association d\'une serre et d\'un système écologique en fait un espace durable et inspirant.', '                Une parcelle moderne et polyvalente, équipée pour accueillir des projets innovants. L\'association d\'une serre et d\'un système écologique en fait un espace durable et inspirant.            ', '../../../public/uploads/20140613_682392997539af0a39ba12.jpg', 65);
